pub fn computeGraphemeBreak(gb1: types.GraphemeBreak, gb2: types.GraphemeBreak, state: *BreakState) bool {
        switch (state.*) {
.regional_indicator => {
if (((gb1 != .regional_indicator) or (gb2 != .regional_indicator))) {
            state.* = .default;
        }
},
.extended_pictographic => {
switch (gb1) {
.indic_conjunct_break_extend, .indic_conjunct_break_linker, .zwnj, .zwj, .extended_pictographic, .emoji_modifier_base, .emoji_modifier => {

},
else => {
state.* = .default;
},
}
        switch (gb2) {
.indic_conjunct_break_extend, .indic_conjunct_break_linker, .zwnj, .zwj, .extended_pictographic, .emoji_modifier_base, .emoji_modifier => {

},
else => {
state.* = .default;
},
}
},
.indic_conjunct_break_consonant, .indic_conjunct_break_linker => {
switch (gb1) {
.indic_conjunct_break_consonant, .indic_conjunct_break_linker, .indic_conjunct_break_extend, .zwj => {

},
else => {
state.* = .default;
},
}
        switch (gb2) {
.indic_conjunct_break_consonant, .indic_conjunct_break_linker, .indic_conjunct_break_extend, .zwj => {

},
else => {
state.* = .default;
},
}
},
.default => {

},
}
        if (((gb1 == .cr) and (gb2 == .lf))) {
            return false;
        }
        if ((((gb1 == .control) or (gb1 == .cr)) or (gb1 == .lf))) {
            return true;
        }
        if ((((gb2 == .control) or (gb2 == .cr)) or (gb2 == .lf))) {
            return true;
        }
        if ((gb1 == .l)) {
            if (((((gb2 == .l) or (gb2 == .v)) or (gb2 == .lv)) or (gb2 == .lvt))) {
                return false;
            }
        }
        if (((gb1 == .lv) or (gb1 == .v))) {
            if (((gb2 == .v) or (gb2 == .t))) {
                return false;
            }
        }
        if (((gb1 == .lvt) or (gb1 == .t))) {
            if ((gb2 == .t)) {
                return false;
            }
        }
        if ((gb2 == .spacing_mark)) {
            return false;
        }
        if ((gb1 == .prepend)) {
            return false;
        }
        if ((gb1 == .indic_conjunct_break_consonant)) {
            if (isIndicConjunctBreakExtend(gb2)) {
                state.* = .indic_conjunct_break_consonant;
                return false;
            } else {
                if ((gb2 == .indic_conjunct_break_linker)) {
                    state.* = .indic_conjunct_break_linker;
                    return false;
                }
            }
        } else {
            if ((state.* == .indic_conjunct_break_consonant)) {
                if ((gb2 == .indic_conjunct_break_linker)) {
                    state.* = .indic_conjunct_break_linker;
                    return false;
                } else {
                    if (isIndicConjunctBreakExtend(gb2)) {
                        return false;
                    } else {
                        state.* = .default;
                    }
                }
            } else {
                if ((state.* == .indic_conjunct_break_linker)) {
                    if (((gb2 == .indic_conjunct_break_linker) or isIndicConjunctBreakExtend(gb2))) {
                        return false;
                    } else {
                        if ((gb2 == .indic_conjunct_break_consonant)) {
                            state.* = .default;
                            return false;
                        } else {
                            state.* = .default;
                        }
                    }
                }
            }
        }
        if (isExtendedPictographic(gb1)) {
            if ((isExtend(gb2) or (gb2 == .zwj))) {
                state.* = .extended_pictographic;
                return false;
            }
            if (((gb1 == .emoji_modifier_base) and (gb2 == .emoji_modifier))) {
                state.* = .extended_pictographic;
                return false;
            }
        } else {
            if ((state.* == .extended_pictographic)) {
                if (((isExtend(gb1) or (gb1 == .emoji_modifier)) and (isExtend(gb2) or (gb2 == .zwj)))) {
                    return false;
                } else {
                    if (((gb1 == .zwj) and isExtendedPictographic(gb2))) {
                        state.* = .default;
                        return false;
                    } else {
                        state.* = .default;
                    }
                }
            }
        }
        if (((gb1 == .regional_indicator) and (gb2 == .regional_indicator))) {
            if ((state.* == .default)) {
                state.* = .regional_indicator;
                return false;
            } else {
                state.* = .default;
                return true;
            }
        }
        if ((isExtend(gb2) or (gb2 == .zwj))) {
            return false;
        }
        return true;
}

pub fn isIndicConjunctBreakExtend(gb: types.GraphemeBreak) bool {
        return ((gb == .indic_conjunct_break_extend) or (gb == .zwj));
}

pub fn isExtend(gb: types.GraphemeBreak) bool {
        return (((gb == .zwnj) or (gb == .indic_conjunct_break_extend)) or (gb == .indic_conjunct_break_linker));
}

pub fn isExtendedPictographic(gb: types.GraphemeBreak) bool {
        return ((gb == .extended_pictographic) or (gb == .emoji_modifier_base));
}

pub fn testGraphemeBreak(getActualIsBreak: *const fn (u21, u21, *BreakState) bool) !void {
        const trim = Ucd.trim;
        const parseCp = Ucd.parseCp;
        const allocator = std.testing.allocator;
        const file_path: []const u8 = "ucd/auxiliary/GraphemeBreakTest.txt";
        const file = try std.fs.cwd().openFile(file_path, .{});
        defer {
        _ = file.close();
        }
        const content = try file.readToEndAlloc(allocator, ((1024 * 1024) * 10));
        defer {
        _ = allocator.free(content);
        }
        var lines = std.mem.splitScalar(u8, content, 10);
        _ = &lines;
        var success = true;
        _ = &success;
        var line_num: usize = 1;
        _ = &line_num;
        while (lines.next()) |line| : (line_num = (line_num + 1)) {
            const trimmed = trim(line);
            if ((trimmed.len == 0)) {
                continue;
            }
            var parts = std.mem.splitScalar(u8, trimmed, 32);
            _ = &parts;
            const start = (parts.next()).?;
            _ = try std.testing.expect(std.mem.eql(u8, start, "÷"));
            var state: BreakState = .default;
            _ = &state;
            var cp1 = try parseCp((parts.next()).?);
            _ = &cp1;
            var gb1 = getpkg.get(.grapheme_break, cp1);
            _ = &gb1;
            var expected_str = (parts.next()).?;
            _ = &expected_str;
            var cp2 = try parseCp((parts.next()).?);
            _ = &cp2;
            var gb2 = getpkg.get(.grapheme_break, cp2);
            _ = &gb2;
            var next_expected_str = (parts.next()).?;
            _ = &next_expected_str;
            while (true) {
                var expected_is_break = std.mem.eql(u8, expected_str, "÷");
                _ = &expected_is_break;
                const actual_is_break = getActualIsBreak(cp1, cp2, (&state));
                _ = try std.testing.expect((expected_is_break or std.mem.eql(u8, expected_str, "×")));
                if (((gb2 == .emoji_modifier) and (gb1 != .emoji_modifier_base))) {
                    _ = std.debug.assert((!expected_is_break));
                    expected_is_break = true;
                }
                if ((actual_is_break != expected_is_break)) {
                    _ = std.log.err("line={d} cp1={x}, cp2={x}: gb1={}, gb2={}, state={}, expected={}, actual={}", .{ line_num, cp1, cp2, gb1, gb2, state, expected_is_break, actual_is_break });
                    success = false;
                }
                if ((parts.peek() == null)) {
                    break;
                }
                cp1 = cp2;
                gb1 = gb2;
                expected_str = next_expected_str;
                cp2 = try parseCp((parts.next()).?);
                gb2 = getpkg.get(.grapheme_break, cp2);
                next_expected_str = (parts.next()).?;
            }
            _ = try std.testing.expect(std.mem.eql(u8, next_expected_str, "÷"));
        }
        _ = try std.testing.expect(success);
}

pub fn testGetActualComputedGraphemeBreak(cp1: u21, cp2: u21, state: *BreakState) bool {
        const gb1 = getpkg.get(.grapheme_break, cp1);
        const gb2 = getpkg.get(.grapheme_break, cp2);
        return computeGraphemeBreak(gb1, gb2, state);
}

pub fn testGraphemebreaktestTxtComputegraphemebreak() !void {
        _ = try testGraphemeBreak(testGetActualComputedGraphemeBreak);
}

pub fn GraphemeBreakTable(comptime GB: type, comptime State: type) type {
        const Result = packed struct {
        result: bool,
        state: State,
    };
        const gb_fields = @typeInfo(GB).@"enum".fields;
        const state_fields = @typeInfo(State).@"enum".fields;
        const n_gb = gb_fields.len;
        const n_gb_2 = (n_gb * n_gb);
        const n_state = state_fields.len;
        const n = (n_state * n_gb_2);
        _ = std.debug.assert(((if (@typeInfo(@TypeOf(gb_fields[@as(usize, @intCast((gb_fields.len - 1)))])) == .@"enum") @intFromEnum(gb_fields[@as(usize, @intCast((gb_fields.len - 1)))]) else gb_fields[@as(usize, @intCast((gb_fields.len - 1)))].value) == (n_gb - 1)));
        _ = std.debug.assert(((if (@typeInfo(@TypeOf(state_fields[@as(usize, @intCast((state_fields.len - 1)))])) == .@"enum") @intFromEnum(state_fields[@as(usize, @intCast((state_fields.len - 1)))]) else state_fields[@as(usize, @intCast((state_fields.len - 1)))].value) == (n_state - 1)));
        return struct {
    data: [n]Result,

pub inline fn index(gb1: GB, gb2: GB, state: State) usize {
            return (((@intFromEnum(state) * n_gb_2) + (@intFromEnum(gb1) * n_gb)) + @intFromEnum(gb2));
    }

pub fn set(self: *@This(), gb1: GB, gb2: GB, state: State, result: Result) void {
            self.data[cp_cast_int(usize, index(gb1, gb2, state))] = result;
    }

pub fn get(self: @This(), gb1: GB, gb2: GB, state: State) Result {
            return self.data[@as(usize, @intCast(index(gb1, gb2, state)))];
    }
};
}

pub fn buildGraphemeBreakTable(comptime GB: type, comptime State: type, compute: *const fn (GB, GB, *State) bool) GraphemeBreakTable(GB,State) {
        _ = @setEvalBranchQuota(20000);
        var table: GraphemeBreakTable(GB,State) = undefined;
        _ = &table;
        const gb_fields = @typeInfo(GB).@"enum".fields;
        const state_fields = @typeInfo(State).@"enum".fields;
        for (state_fields) |state_field| {
            for (gb_fields) |gb1_field| {
                for (gb_fields) |gb2_field| {
                    const original_state: State = @enumFromInt((if (@typeInfo(@TypeOf(state_field)) == .@"enum") @intFromEnum(state_field) else state_field.value));
                    const gb1: GB = @enumFromInt((if (@typeInfo(@TypeOf(gb1_field)) == .@"enum") @intFromEnum(gb1_field) else gb1_field.value));
                    const gb2: GB = @enumFromInt((if (@typeInfo(@TypeOf(gb2_field)) == .@"enum") @intFromEnum(gb2_field) else gb2_field.value));
                    var state = original_state;
                    _ = &state;
                    const result = compute(gb1, gb2, (&state));
                    _ = table.set(gb1, gb2, original_state, .{ .result = result, .state = state });
                }
            }
        }
        return table;
}

pub fn precomputedGraphemeBreak(gb1: types.GraphemeBreak, gb2: types.GraphemeBreak, state: *BreakState) bool {
        const table = (comptime buildGraphemeBreakTable(types.GraphemeBreak, BreakState, computeGraphemeBreak));
        _ = std.debug.assert((@sizeOf(@TypeOf(table)) == 2000));
        const result = table.get(gb1, gb2, state.*);
        state.* = (result).?.state;
        return (result).?.result;
}

pub fn isBreak(cp1: u21, cp2: u21, state: *BreakState) bool {
        const gb1 = getpkg.get(.grapheme_break, cp1);
        const gb2 = getpkg.get(.grapheme_break, cp2);
        return precomputedGraphemeBreak(gb1, gb2, state);
}

pub fn testGraphemebreaktestTxtIsbreak() !void {
        _ = try testGraphemeBreak(isBreak);
}

